 &lt;tbody&gt;
  &lt;tr&gt;
   &lt;td height="21" width="87"&gt;AWS::Billing::BillingView&lt;/td&gt; 
   &lt;td width="87"&gt;AWS::MPA::IdentitySource&lt;/td&gt; 
  &lt;/tr&gt;
  &lt;tr&gt;
   &lt;td height="21"&gt;AWS::Connect::HoursOfOperation&lt;/td&gt; 
