  &lt;/tr&gt;
  &lt;tr&gt;
   &lt;td height="21"&gt;AWS::ElastiCache::CacheCluster&lt;/td&gt; 
   &lt;td&gt;AWS::NotificationsContacts::EmailContact&lt;/td&gt; 
  &lt;/tr&gt;
  &lt;tr&gt;
